package hu.bankmonitor.payments.transfers;

import java.time.Instant;
import java.util.Objects;

/**
 * What a caller has to say to request a Transfer: the two Accounts, how much to move, and
 * when it was asked for.
 *
 * <p><b>The amount is a bare count of Minor Units and not {@link
 * hu.bankmonitor.payments.common.Money}</b>, which is the one place in this context where a
 * number without a Currency is the honest shape. The Currency of a Transfer is the source
 * Account's, and the source Account is only read under the row lock design decision 6
 * requires — so a caller could only name a Currency here by reading the Account first,
 * outside the lock, which is the read that design decision exists to forbid. The count
 * becomes Money inside {@link FundsReservation}, at the first moment there is an Account to
 * denominate it.
 *
 * <p>Design decision 15 locks the Exchange Rate at request time, so ticket 26 will bring a
 * second amount for the credited side. Until then both sides of a Transfer are the same
 * figure and this carries it once.
 */
public record ReservationRequest(
		long sourceAccountId,
		long destinationAccountId,
		long amountMinorUnits,
		Instant requestedAt) {

	public ReservationRequest {
		Objects.requireNonNull(requestedAt, "a transfer is requested at a time");
	}
}
=====ADVICE=====
package hu.bankmonitor.payments.transfers;

import hu.bankmonitor.payments.accounts.InsufficientFundsException;
import hu.bankmonitor.payments.accounts.UnknownAccountException;
import hu.bankmonitor.payments.common.ProblemType;
import jakarta.servlet.http.HttpServletRequest;
import org.springframework.core.Ordered;
import org.springframework.core.annotation.Order;
import org.springframework.http.HttpStatus;
import org.springframework.http.ProblemDetail;
import org.springframework.web.bind.annotation.ExceptionHandler;
import org.springframework.web.bind.annotation.RestControllerAdvice;

import java.net.URI;

/**
 * What the transfers slice's own refusals look like to a client: a {@code 422}, and the
 * {@link ProblemType} URN that says which one it is.
 *
 * <p>The mapping lives in this slice rather than in {@code ProblemDocumentAdvice}, which
 * adopts the framework's failures and belongs to no slice. What a refused Transfer means to
 * a caller is this package's decision, and it is made beside the code that raises it.
 *
 * <p><b>Every refusal here is {@code 422} rather than {@code 400}.</b> Each arrives from
 * under the lock, decided against Accounts the request could not see — so the request was
 * well-formed and this API understood it, which is exactly the distinction the two statuses
 * draw. A {@code 404} for an unknown Account was rejected for a sharper reason: this API
 * answers {@code 404} when the <em>path</em> names nothing, and {@code /api/transfers}
 * always exists. Reusing it for an Account ID inside the body would have two meanings
 * behind one status.
 *
 * <p>Every {@code detail} is written here rather than taken from the exception, on
 * {@code ProblemDocumentAdvice}'s reasoning: an exception message is written for a log, and
 * two of these carry {@code Money}, whose {@code toString} is a record's.
 *
 * <p><b>The ordering is load-bearing and fails silently without it.</b> Spring asks each
 * {@code @ControllerAdvice} in order for a handler and takes the first that has one;
 * {@code ProblemDocumentAdvice} declares a handler for {@code Exception}, so an unordered
 * advice may never be consulted at all and every refusal below would answer {@code 500}
 * instead — as a {@code 500} that looks exactly like a genuine one.
 */
@Order(Ordered.HIGHEST_PRECEDENCE)
@RestControllerAdvice(assignableTypes = TransferController.class)
class TransferRefusalAdvice {

	private static final String SELF_TRANSFER_DETAIL =
			"A Transfer must move money between two different Accounts.";

	private static final String UNKNOWN_ACCOUNT_DETAIL = "No Account has that identifier.";

	private static final String INSUFFICIENT_FUNDS_DETAIL =
			"The source Account's Available Balance does not cover this Transfer.";

	private static final String CROSS_CURRENCY_DETAIL =
			"This service cannot yet convert between the two Accounts' Currencies.";

	@ExceptionHandler
	ProblemDetail handleSelfTransfer(SelfTransferNotAllowedException refusal, HttpServletRequest request) {
		ProblemDetail problem = refusalOf(ProblemType.SELF_TRANSFER, SELF_TRANSFER_DETAIL, request);
		problem.setProperty("accountId", refusal.getAccountId());
		return problem;
	}

	@ExceptionHandler
	ProblemDetail handleUnknownAccount(UnknownAccountException refusal, HttpServletRequest request) {
		ProblemDetail problem = refusalOf(ProblemType.UNKNOWN_ACCOUNT, UNKNOWN_ACCOUNT_DETAIL, request);
		problem.setProperty("accountId", refusal.getAccountId());
		return problem;
	}

	/**
	 * Both figures that were compared, and the Currency they were compared in — which is one
	 * member rather than two because an Available Balance and the amount tested against it
	 * cannot be denominated differently and still have been compared.
	 */
	@ExceptionHandler
	ProblemDetail handleInsufficientFunds(InsufficientFundsException refusal, HttpServletRequest request) {
		ProblemDetail problem = refusalOf(ProblemType.INSUFFICIENT_FUNDS, INSUFFICIENT_FUNDS_DETAIL, request);
		problem.setProperty("availableBalanceMinorUnits", refusal.getAvailableBalance().minorUnits());
