	ProblemDetail handleCrossCurrencyTransfer(CrossCurrencyTransferNotSupportedException refusal,
			HttpServletRequest request) {
		ProblemDetail problem = refusalOf(ProblemType.CROSS_CURRENCY_UNSUPPORTED, CROSS_CURRENCY_DETAIL, request);
		problem.setProperty("sourceCurrency", refusal.getSourceCurrency());
		problem.setProperty("destinationCurrency", refusal.getDestinationCurrency());
		return problem;
	}

	/**
	 * The parts every refusal shares. {@code instance} is set by hand because the base class
	 * that would otherwise do it is the one this advice deliberately is not, and a document
	 * missing it would be the one shape a client could not treat like the others.
	 */
	private static ProblemDetail refusalOf(ProblemType type, String detail, HttpServletRequest request) {
		ProblemDetail problem = ProblemDetail.forStatusAndDetail(HttpStatus.UNPROCESSABLE_ENTITY, detail);
		problem.setType(type.uri());
		problem.setInstance(URI.create(request.getRequestURI()));
		return problem;
	}
}

